    """The rate of a rep for a product line, in basis points."""
    key = (rep_id, product_line)
    if key not in _looked_up:
        row = conn.execute(
            "SELECT rate_bp FROM rate_table WHERE rep_id = ? AND product_line = ?",
            (rep_id, product_line),
        ).fetchone()
        if row is None:
            row = conn.execute(
                "SELECT rate_bp FROM rate_table WHERE rep_id = '*' AND product_line = ?",
